data.query:
query Workcenter($where: WorkcenterWhereInput, $orderBy: [WorkcenterOrderByInput!], $first: Int, $after: String) {
  workcenter(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        isActive
        code
        cellId
        currentWorkOrderId
        lineId
      }
    }
  }
}

query Product($where: ProductWhereInput, $orderBy: [ProductOrderByInput!], $first: Int, $after: String) {
  product(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        setupTime
        standardCycleTime
        targetYield
        isActive
        code
        productFamily
        unitId
        workcenterId
      }
    }
  }
}

