// Access context differently in Fuuz transformations
const stateContext = $state && $state.context ? $state.context : {};

// Get config from context
const config = stateContext.avgOrdersPerWorkcenter ? stateContext : {
  minOrderDurationHours: 24,        // Minimum 24 hours per order
  maxOrderDurationHours: 72,        // Maximum 72 hours per order
  targetWeekCapacity: 1.10,         // 110% of week capacity
  priorityWeights: { "1": 0.10, "3": 0.20, "5": 0.40, "7": 0.20, "9": 0.10 }
};

// Extract workcenters and products from context
const workcenters = stateContext.workcenters && stateContext.workcenters.edges 
  ? stateContext.workcenters.edges.map(e => e.node)
  : [];

const products = stateContext.products && stateContext.products.edges
  ? stateContext.products.edges.map(e => e.node)
  : [];

// Calculate week start (Sunday)
const now = new Date();
const startOfWeek = new Date(now);
startOfWeek.setDate(now.getDate() - now.getDay());
startOfWeek.setHours(0, 0, 0, 0);

// ═══════════════════════════════════════════════════════════════════════
// CAPACITY PLANNING CONSTANTS
// ═══════════════════════════════════════════════════════════════════════
const HOURS_PER_WEEK = 7 * 24;  // 168 hours
const TARGET_CAPACITY_HOURS = HOURS_PER_WEEK * config.targetWeekCapacity;  // 184.8 hours at 110%
const MIN_ORDER_HOURS = config.minOrderDurationHours;  // 24 hours minimum
const MAX_ORDER_HOURS = config.maxOrderDurationHours;  // 72 hours maximum

console.log('═══════════════════════════════════════════════════════════');
console.log('WORK ORDER GENERATION - CAPACITY BASED');
console.log('═══════════════════════════════════════════════════════════');
console.log('Target capacity per workcenter: ' + TARGET_CAPACITY_HOURS.toFixed(1) + ' hours (' + (TARGET_CAPACITY_HOURS / 24).toFixed(1) + ' days)');
console.log('Order duration range: ' + MIN_ORDER_HOURS + '-' + MAX_ORDER_HOURS + ' hours');
console.log('Week start: ' + startOfWeek.toISOString().slice(0, 10));
console.log('───────────────────────────────────────────────────────────');

// Helper functions
function randomInRange(min, max) {
  return Math.random() * (max - min) + min;
}

function randomInt(min, max) {
  return Math.floor(randomInRange(min, max + 1));
}

function getRandomPriority() {
  const rand = Math.random();
  let cumulative = 0;
  for (const [priority, weight] of Object.entries(config.priorityWeights)) {
    cumulative += weight;
    if (rand <= cumulative) return parseInt(priority);
  }
  return 5;
}

// ═══════════════════════════════════════════════════════════════════════
// CALCULATE ORDER QUANTITY BASED ON DESIRED DURATION
// ═══════════════════════════════════════════════════════════════════════
function calculateOrderQuantity(product, targetHours) {
  const { standardCycleTime, targetYield = 99 } = product;
  
  // standardCycleTime is in seconds per unit
  // targetHours is how long we want this order to run
  const targetSeconds = targetHours * 3600;
  
  // Calculate raw quantity needed for target duration
  const rawQuantity = targetSeconds / standardCycleTime;
  
  // Account for yield to determine target quantity
  // If yield is 99%, we need 1% more to get the target good units
  const yieldDecimal = targetYield / 100;
  const targetQuantity = Math.ceil(rawQuantity * yieldDecimal);
  
  return targetQuantity;
}

// ═══════════════════════════════════════════════════════════════════════
// CALCULATE ORDER DURATION BASED ON QUANTITY
// ═══════════════════════════════════════════════════════════════════════
function calculateOrderDuration(product, quantity) {
  const { standardCycleTime, setupTime = 0 } = product;
  
  // Setup time is in minutes
  const setupHours = setupTime / 60;
  
  // Production time: (quantity * seconds per unit) / 3600 = hours
  const productionHours = (quantity * standardCycleTime) / 3600;
  
  const totalHours = setupHours + productionHours;
  
  return {
    setupHours: setupHours,
    productionHours: productionHours,
    totalHours: totalHours
  };
}

// ═══════════════════════════════════════════════════════════════════════
// UNIQUE CODE GENERATOR
// ═══════════════════════════════════════════════════════════════════════
function generateWorkOrderCode(workcenterCode, sequence) {
  const dateTimePart = new Date().toISOString()
    .replace(/[-:T]/g, '')
    .slice(0, 14);
  
  const randomSuffix = Math.random().toString(36).substr(2, 3).toUpperCase();
  
  return `WO-${workcenterCode}-${dateTimePart}-${randomSuffix}`;
}

// ═══════════════════════════════════════════════════════════════════════
// CALCULATE SCHEDULED DATES
// ═══════════════════════════════════════════════════════════════════════
function calculateScheduledDates(product, quantity, startDate) {
  const duration = calculateOrderDuration(product, quantity);
  const totalMinutes = duration.totalHours * 60;
  
  const scheduledStartAt = new Date(startDate);
  const scheduledEndAt = new Date(scheduledStartAt.getTime() + totalMinutes * 60000);
  
  return {
    scheduledStartAt: scheduledStartAt.toISOString(),
    scheduledEndAt: scheduledEndAt.toISOString(),
    durationHours: duration.totalHours
  };
}

// ═══════════════════════════════════════════════════════════════════════
// GROUP PRODUCTS BY WORKCENTER
// ═══════════════════════════════════════════════════════════════════════
const productsByWorkcenter = {};
products.forEach(product => {
  if (!productsByWorkcenter[product.workcenterId]) {
    productsByWorkcenter[product.workcenterId] = [];
  }
  productsByWorkcenter[product.workcenterId].push(product);
});

// ═══════════════════════════════════════════════════════════════════════
// GENERATE WORK ORDERS WITH CAPACITY PLANNING
// ═══════════════════════════════════════════════════════════════════════
const workOrders = [];
const workcenterStats = [];

workcenters.forEach(workcenter => {
  const wcProducts = productsByWorkcenter[workcenter.id] || [];
  if (wcProducts.length === 0) {
    console.log('Workcenter ' + workcenter.code + ': No products, skipping');
    return;
  }
  
  console.log('\nWorkcenter ' + workcenter.code + ':');
  console.log('  Products available: ' + wcProducts.length);
  
  let totalScheduledHours = 0;
  let orderCount = 0;
  let currentStartTime = new Date(startOfWeek);
  
  // Keep generating orders until we reach 110% capacity
  while (totalScheduledHours < TARGET_CAPACITY_HOURS) {
    // Calculate remaining capacity
    const remainingHours = TARGET_CAPACITY_HOURS - totalScheduledHours;
    
    // Determine order duration (random between min and max, but not more than remaining)
    let orderDuration = randomInRange(MIN_ORDER_HOURS, MAX_ORDER_HOURS);
    orderDuration = Math.min(orderDuration, remainingHours);
    
    // If remaining capacity is too small for a meaningful order, add one more full order
    if (remainingHours < MIN_ORDER_HOURS && orderCount > 0) {
      orderDuration = MIN_ORDER_HOURS;
    }
    
    // Skip if duration too small
    if (orderDuration < 1) {
      break;
    }
    
    // Select random product
    const product = wcProducts[randomInt(0, wcProducts.length - 1)];
    const quantity = calculateOrderQuantity(product, orderDuration);
    const priority = getRandomPriority();
    
    // Calculate actual duration with this quantity
    const schedule = calculateScheduledDates(product, quantity, currentStartTime);
    const actualDuration = schedule.durationHours;
    
    workOrders.push({
      create: {
        code: generateWorkOrderCode(workcenter.code, orderCount + 1),
        productId: product.id,
        workcenterId: workcenter.id,
        quantityTarget: quantity,
        quantityCompleted: 0,
        quantityScrap: 0,
        priority: priority,
        status: 'Released',
        scheduledStartAt: schedule.scheduledStartAt,
        scheduledEndAt: schedule.scheduledEndAt,
        notes: 'Auto-generated for week of ' + startOfWeek.toISOString().slice(0, 10) + ' - Duration: ' + actualDuration.toFixed(1) + 'h'
      }
    });
    
    // Update tracking
    totalScheduledHours += actualDuration;
    orderCount++;
    
    // Move start time forward for next order
    currentStartTime = new Date(schedule.scheduledEndAt);
    
    console.log('  Order ' + orderCount + ': ' + product.code + ', ' + quantity + ' units, ' + actualDuration.toFixed(1) + 'h (Total: ' + totalScheduledHours.toFixed(1) + 'h)');
  }
  
  const utilizationPercent = (totalScheduledHours / HOURS_PER_WEEK) * 100;
  
  workcenterStats.push({
    workcenterId: workcenter.id,
    workcenterCode: workcenter.code,
    ordersGenerated: orderCount,
    totalScheduledHours: Math.round(totalScheduledHours * 10) / 10,
    totalScheduledDays: Math.round((totalScheduledHours / 24) * 10) / 10,
    utilizationPercent: Math.round(utilizationPercent * 10) / 10,
    targetCapacityHours: TARGET_CAPACITY_HOURS
  });
  
  console.log('  Summary: ' + orderCount + ' orders, ' + totalScheduledHours.toFixed(1) + ' hours (' + (totalScheduledHours / 24).toFixed(1) + ' days), ' + utilizationPercent.toFixed(1) + '% utilization');
});

// ═══════════════════════════════════════════════════════════════════════
// CALCULATE OVERALL STATISTICS
// ═══════════════════════════════════════════════════════════════════════
const totalHoursScheduled = workcenterStats.reduce((sum, wc) => sum + wc.totalScheduledHours, 0);
const avgUtilization = workcenterStats.length > 0 
  ? workcenterStats.reduce((sum, wc) => sum + wc.utilizationPercent, 0) / workcenterStats.length
  : 0;

console.log('\n═══════════════════════════════════════════════════════════');
console.log('GENERATION COMPLETE');
console.log('═══════════════════════════════════════════════════════════');
console.log('Total work orders: ' + workOrders.length);
console.log('Workcenters processed: ' + workcenters.length);
console.log('Total hours scheduled: ' + totalHoursScheduled.toFixed(1) + ' hours');
console.log('Average utilization: ' + avgUtilization.toFixed(1) + '%');
console.log('═══════════════════════════════════════════════════════════');

return {
  workOrders: workOrders,
  summary: {
    totalOrders: workOrders.length,
    workcentersProcessed: workcenters.length,
    productsAvailable: products.length,
    weekStart: startOfWeek.toISOString().slice(0, 10),
    targetCapacityHours: TARGET_CAPACITY_HOURS,
    totalHoursScheduled: Math.round(totalHoursScheduled * 10) / 10,
    totalDaysScheduled: Math.round((totalHoursScheduled / 24) * 10) / 10,
    averageUtilization: Math.round(avgUtilization * 10) / 10,
    workcenterStats: workcenterStats
  }
};

